import {
  DriverError,
  diffKeyEntries,
  foreignKeyActionSuffix,
  generateKeyName,
  type DatabaseSpec,
  type DdlStatement,
  type ForeignKeySpec,
  type TableSpec,
} from '@db-explorer/core';
import { quotePgIdentifier } from './sql';

/**
 * PostgreSQL 表结构编辑语句生成（M8-B2/M8-PG，概要 §5.9 / 驱动规范 §3 @since v0.1.2）：
 * - DDL 不可参数化（PG PREPARE 不支持 DDL，驱动规范 §10）：标识符 fail-closed 校验
 *   （非法字符直接 E_VALIDATION，不靠转义兜底）+ 双引号引用；字面量转义，控制字符拒绝
 *   （PG standard_conforming_strings 下反斜杠为字面量，无需拒绝）
 * - 自增用 IDENTITY（PG 10+ 推荐，区别于 MySQL AUTO_INCREMENT）：GENERATED BY DEFAULT AS IDENTITY
 * - 注释无内联语法：COMMENT ON TABLE/COLUMN 独立语句（随语句集执行）
 * - ALTER 序列（D-15 定稿口径）：RENAME → 新主键列 SET NOT NULL → DROP CONSTRAINT（旧主键，
 *   destructive）→ DROP COLUMN（destructive）→ ADD COLUMN → 逐属性 ALTER → ADD PRIMARY KEY → COMMENT
 *   （删主键列前必须先删主键约束，否则依赖报错）
 * - 与 previewChanges/applyChanges 同源原则对应：ddl.preview 与 ddl.execute 都经 Host 重新
 *   调用本模块生成语句，此处只做纯生成
 * 纯函数，有单测。
 */

/** 标识符校验（白名单 → 危险字符黑名单）：只拒绝方言引号字符（双引号，防逃逸）与控制字符；
 *  连字符/点/空格/中文等真实合法名交由 quotePgIdentifier 双写转义承载——DDL 不可参数化的
 *  fail-closed 口径不变（注入面即引号逃逸，已从源头封死） */
// eslint-disable-next-line no-control-regex -- 刻意匹配控制字符：拒绝它们正是本校验的职责（escapeDdlLiteral 同款豁免）
const IDENT_DANGEROUS_RE = /[\u0000-\u001F\u007F"]/;

function assertIdentifier(kind: string, name: string): string {
  if (!name || name.length > 128 || IDENT_DANGEROUS_RE.test(name)) {
    throw new DriverError('E_VALIDATION', `${kind} "${name}" 含非法字符（方言引号字符与控制字符不允许）`);
  }
  return name;
}

/** 字面量转义：数值与 CURRENT_TIMESTAMP/CURRENT_DATE 原样；其余字符串字面量单引号包裹（'' 翻倍）；控制字符拒绝 */
export function escapeDdlLiteral(value: string): string {
  if (/^-?\d+(\.\d+)?$/.test(value) || /^CURRENT_(TIMESTAMP|DATE|TIME)$/i.test(value.trim())) {
    return value.trim();
  }
  // eslint-disable-next-line no-control-regex -- 刻意拒绝控制字符（驱动规范 §10 fail-closed）
  if (/[\r\n\x00]/.test(value)) {
    throw new DriverError('E_VALIDATION', '默认值不允许包含换行或控制字符');
  }
  return `'${value.replace(/'/g, "''")}'`;
}

/** 注释文本转义（COMMENT ON；控制字符拒绝） */
function escapeComment(value: string): string {
  // eslint-disable-next-line no-control-regex -- 刻意拒绝控制字符（驱动规范 §10 fail-closed）
  if (/[\r\n\x00]/.test(value)) {
    throw new DriverError('E_VALIDATION', '注释不允许包含换行或控制字符');
  }
  return `'${value.replace(/'/g, "''")}'`;
}

/** 自增列：IDENTITY（隐含 NOT NULL）；identity 要求列为 int/integer/bigint 族（由 dataType 原文承载，PG 校验） */
function columnDefSql(col: TableSpec['columns'][number]): string {
  const parts = [quotePgIdentifier(assertIdentifier('列名', col.name)), col.dataType.trim()];
  if (col.autoIncrement) {
    parts.push('GENERATED BY DEFAULT AS IDENTITY');
  }
  parts.push(col.nullable ? 'NULL' : 'NOT NULL');
  if (col.defaultValue !== undefined && col.defaultValue !== '') {
    parts.push(`DEFAULT ${escapeDdlLiteral(col.defaultValue)}`);
  }
  return parts.join(' ');
}

function commentOnStatements(db: string, spec: TableSpec): DdlStatement[] {
  const statements: DdlStatement[] = [];
  const qualified = `${quotePgIdentifier(db)}.${quotePgIdentifier(spec.name)}`;
  if (spec.comment) {
    statements.push({ sql: `COMMENT ON TABLE ${qualified} IS ${escapeComment(spec.comment)}` });
  }
  for (const col of spec.columns) {
    if (col.comment) {
      statements.push({
        sql: `COMMENT ON COLUMN ${qualified}.${quotePgIdentifier(assertIdentifier('列名', col.name))} IS ${escapeComment(col.comment)}`,
      });
    }
  }
  return statements;
}

/** 列名清单字面量（键/外键/索引共用，表设计器批次 B） */
function columnListLit(columns: readonly string[]): string {
  if (columns.length === 0) {
    throw new DriverError('E_VALIDATION', '键/索引至少需要一列');
  }
  return columns.map((c) => quotePgIdentifier(assertIdentifier('列名', c))).join(', ');
}

/** 唯一键/外键的 CREATE TABLE 内联 CONSTRAINT 子句（PG 无内联 INDEX——索引走独立 CREATE INDEX）；
 *  命名 fail-closed（未命名自动 uk_/fk_/idx_ 表名_序号），外键引用列数须与本地一致 */
function appendCreateConstraintClauses(cols: string[], spec: TableSpec): void {
  const taken = new Set<string>();
  for (const k of [...(spec.uniqueKeys ?? []), ...(spec.foreignKeys ?? [])]) {
    if (k.name) {
      taken.add(k.name);
    }
  }
  for (const uk of spec.uniqueKeys ?? []) {
    const name = assertIdentifier('唯一键名', uk.name ?? generateKeyName('uk', spec.name, taken));
    taken.add(name);
    cols.push(`CONSTRAINT ${quotePgIdentifier(name)} UNIQUE (${columnListLit(uk.columns)})`);
  }
  for (const fk of spec.foreignKeys ?? []) {
    if (fk.refColumns.length !== fk.columns.length) {
      throw new DriverError('E_VALIDATION', `外键 "${fk.name ?? '(未命名)'}" 引用列数须与本地列数一致`);
    }
    const name = assertIdentifier('外键名', fk.name ?? generateKeyName('fk', spec.name, taken));
    taken.add(name);
    cols.push(
      `CONSTRAINT ${quotePgIdentifier(name)} FOREIGN KEY (${columnListLit(fk.columns)}) REFERENCES ${quotePgIdentifier(assertIdentifier('引用表名', fk.refTable))} (${columnListLit(fk.refColumns)})${foreignKeyActionSuffix(fk)}`,
    );
  }
}

/** 索引方法子句（PG CREATE INDEX 的 USING；缺省 = 服务端默认 btree） */
function pgIndexTypeSuffix(type: string | undefined): string {
  return type ? ` USING ${assertIdentifier('索引类型', type)}` : '';
}

/** 二级索引独立语句（CREATE [UNIQUE] INDEX；PG 建表无内联索引语法） */
function createIndexStatements(db: string, spec: TableSpec): DdlStatement[] {
  const taken = new Set((spec.uniqueKeys ?? []).map((k) => k.name).filter(Boolean) as string[]);
  const qualified = `${quotePgIdentifier(db)}.${quotePgIdentifier(spec.name)}`;
  return (spec.indexes ?? []).map((idx) => {
    const name = assertIdentifier('索引名', idx.name ?? generateKeyName('idx', spec.name, taken));
    taken.add(name);
    return {
      sql: `CREATE ${idx.unique ? 'UNIQUE ' : ''}INDEX ${quotePgIdentifier(name)} ON ${qualified} (${columnListLit(idx.columns)})${pgIndexTypeSuffix(idx.type)}`,
    };
  });
}

export function buildCreateTableStatements(db: string, spec: TableSpec): DdlStatement[] {
  assertIdentifier('库名', db);
  assertIdentifier('表名', spec.name);
  if (spec.columns.length === 0) {
    throw new DriverError('E_VALIDATION', '表至少需要一列');
  }
  for (const c of spec.columns) {
    assertIdentifier('列名', c.name);
  }
  const cols = spec.columns.map(columnDefSql);
  const pk = spec.columns.filter((c) => c.isPrimaryKey).map((c) => quotePgIdentifier(c.name));
  if (pk.length > 0) {
    cols.push(`PRIMARY KEY (${pk.join(', ')})`);
  }
  appendCreateConstraintClauses(cols, spec);
  const create = `CREATE TABLE ${quotePgIdentifier(db)}.${quotePgIdentifier(spec.name)} (\n  ${cols.join(',\n  ')}\n)`;
  return [{ sql: create }, ...createIndexStatements(db, spec), ...commentOnStatements(db, spec)];
}

export function buildAlterTableStatements(
  db: string,
  obj: string,
  spec: TableSpec,
  current: TableSpec,
): DdlStatement[] {
  assertIdentifier('库名', db);
  assertIdentifier('表名', spec.name);
  assertIdentifier('表名', obj);
  for (const c of spec.columns) {
    assertIdentifier('列名', c.name);
  }
  const statements: DdlStatement[] = [];
  const alterPrefix = `${quotePgIdentifier(db)}.${quotePgIdentifier(spec.name)}`;

  // 重命名（PG RENAME TO 不带 schema 目标，同名库内）
  if (spec.name !== obj) {
    statements.push({ sql: `ALTER TABLE ${quotePgIdentifier(db)}.${quotePgIdentifier(obj)} RENAME TO ${quotePgIdentifier(spec.name)}` });
  }

  const curByName = new Map(current.columns.map((c) => [c.name, c]));
  const tgtByName = new Map(spec.columns.map((c) => [c.name, c]));

  const curPk = current.columns.filter((c) => c.isPrimaryKey).map((c) => c.name);
  const tgtPk = spec.columns.filter((c) => c.isPrimaryKey).map((c) => c.name);
  const pkChanged = curPk.join(',') !== tgtPk.join(',');

  // 新主键列的非空约束先于约束重建（PG ADD PRIMARY KEY 要求列 NOT NULL）；
  // 已在此处理的列跳过逐属性 ALTER 的重复 SET NOT NULL
  const pkNotNullDone = new Set<string>();
  if (pkChanged) {
    for (const name of tgtPk) {
      const cur = curByName.get(name);
      if (cur && cur.nullable) {
        statements.push({ sql: `ALTER TABLE ${alterPrefix} ALTER COLUMN ${quotePgIdentifier(name)} SET NOT NULL` });
        pkNotNullDone.add(name);
      }
    }
    // 旧主键约束先删（PG 无 DROP PRIMARY KEY；约束名按 PG 默认 <表名>_pkey，重命名前建表名 = obj）
    if (curPk.length > 0) {
      statements.push({
        sql: `ALTER TABLE ${alterPrefix} DROP CONSTRAINT IF EXISTS ${quotePgIdentifier(`${obj}_pkey`)}`,
        destructive: true,
      });
    }
  }

  // ── 键/外键/索引 diff 删除半段（表设计器批次 B，§12.7 红线：DROP 只由「基线存在且 spec 移除」
  // 生成）——必须在列删除之前：PG 对被外键/索引依赖的列直接拒绝 DROP COLUMN
  const taken = new Set<string>();
  for (const k of [...(current.uniqueKeys ?? []), ...(current.foreignKeys ?? []), ...(current.indexes ?? [])]) {
    if (k.name) {
      taken.add(k.name);
    }
  }
  const ukDiff = diffKeyEntries(spec.uniqueKeys, current.uniqueKeys);
  const fkDiff = diffKeyEntries<ForeignKeySpec>(spec.foreignKeys, current.foreignKeys);
  const idxDiff = diffKeyEntries(spec.indexes, current.indexes);
  for (const k of [...fkDiff.dropped, ...fkDiff.changed]) {
    statements.push({ sql: `ALTER TABLE ${alterPrefix} DROP CONSTRAINT ${quotePgIdentifier(assertIdentifier('外键名', k.name!))}` });
  }
  for (const k of [...ukDiff.dropped, ...ukDiff.changed]) {
    statements.push({ sql: `ALTER TABLE ${alterPrefix} DROP CONSTRAINT ${quotePgIdentifier(assertIdentifier('唯一键名', k.name!))}` });
  }
  for (const k of [...idxDiff.dropped, ...idxDiff.changed]) {
    statements.push({ sql: `DROP INDEX ${quotePgIdentifier(db)}.${quotePgIdentifier(assertIdentifier('索引名', k.name!))}` });
  }

  // 删列（可能丢数据 → destructive；主键列依赖已在上文解除）
  for (const cur of current.columns) {
    if (!tgtByName.has(cur.name)) {
      statements.push({
        sql: `ALTER TABLE ${alterPrefix} DROP COLUMN ${quotePgIdentifier(cur.name)}`,
        destructive: true,
      });
    }
  }

  // 加列（行数据不丢 → 非 destructive）
  for (const tgt of spec.columns) {
    if (!curByName.has(tgt.name)) {
      statements.push({ sql: `ALTER TABLE ${alterPrefix} ADD COLUMN ${columnDefSql(tgt)}` });
    }
  }

  // 改列（逐属性 ALTER；类型变化标 destructive——可能截断/丢数据）
  for (const tgt of spec.columns) {
    const cur = curByName.get(tgt.name);
    if (!cur) {
      continue;
    }
    const colPrefix = `ALTER TABLE ${alterPrefix} ALTER COLUMN ${quotePgIdentifier(tgt.name)}`;
    if (cur.dataType.trim() !== tgt.dataType.trim()) {
      // USING 显式转换：跨类别类型变更（varchar→int 等）可执行；不兼容对由 PG 报错定位
      statements.push({
        sql: `${colPrefix} TYPE ${tgt.dataType.trim()} USING ${quotePgIdentifier(tgt.name)}::${tgt.dataType.trim()}`,
        destructive: true,
      });
    }
    if (cur.nullable !== tgt.nullable && !pkNotNullDone.has(tgt.name)) {
      statements.push({ sql: `${colPrefix} ${tgt.nullable ? 'DROP' : 'SET'} NOT NULL` });
    }
    const curDefault = cur.defaultValue ?? '';
    const tgtDefault = tgt.defaultValue ?? '';
    if (curDefault !== tgtDefault) {
      statements.push({
        sql: tgtDefault ? `${colPrefix} SET DEFAULT ${escapeDdlLiteral(tgtDefault)}` : `${colPrefix} DROP DEFAULT`,
      });
    }
    if (Boolean(cur.autoIncrement) !== Boolean(tgt.autoIncrement)) {
      statements.push({
        sql: tgt.autoIncrement
          ? `${colPrefix} ADD GENERATED BY DEFAULT AS IDENTITY`
          : `${colPrefix} DROP IDENTITY IF EXISTS`,
      });
    }
    if ((cur.comment ?? '') !== (tgt.comment ?? '')) {
      statements.push({
        sql: `COMMENT ON COLUMN ${alterPrefix}.${quotePgIdentifier(tgt.name)} IS ${tgt.comment ? escapeComment(tgt.comment) : 'NULL'}`,
      });
    }
  }

  // 主键重建（DROP 已在上文）
  if (pkChanged && tgtPk.length > 0) {
    statements.push({
      sql: `ALTER TABLE ${alterPrefix} ADD PRIMARY KEY (${tgtPk.map((n) => quotePgIdentifier(n)).join(', ')})`,
    });
  }

  // ── 键/外键/索引 diff 添加半段（列变更之后：外键/索引可引用新加列）
  for (const k of [...ukDiff.added, ...ukDiff.changed]) {
    const name = assertIdentifier('唯一键名', k.name ?? generateKeyName('uk', spec.name, taken));
    taken.add(name);
    statements.push({ sql: `ALTER TABLE ${alterPrefix} ADD CONSTRAINT ${quotePgIdentifier(name)} UNIQUE (${columnListLit(k.columns)})` });
  }
  for (const k of [...fkDiff.added, ...fkDiff.changed]) {
    if (k.refColumns.length !== k.columns.length) {
      throw new DriverError('E_VALIDATION', `外键 "${k.name ?? '(未命名)'}" 引用列数须与本地列数一致`);
    }
    const name = assertIdentifier('外键名', k.name ?? generateKeyName('fk', spec.name, taken));
    taken.add(name);
    statements.push({
      sql: `ALTER TABLE ${alterPrefix} ADD CONSTRAINT ${quotePgIdentifier(name)} FOREIGN KEY (${columnListLit(k.columns)}) REFERENCES ${quotePgIdentifier(assertIdentifier('引用表名', k.refTable))} (${columnListLit(k.refColumns)})${foreignKeyActionSuffix(k)}`,
    });
  }
  for (const k of [...idxDiff.added, ...idxDiff.changed]) {
    const name = assertIdentifier('索引名', k.name ?? generateKeyName('idx', spec.name, taken));
    taken.add(name);
    statements.push({
      sql: `CREATE ${k.unique ? 'UNIQUE ' : ''}INDEX ${quotePgIdentifier(name)} ON ${alterPrefix} (${columnListLit(k.columns)})${pgIndexTypeSuffix(k.type)}`,
    });
  }

  // 表注释
  if ((spec.comment ?? '') !== (current.comment ?? '')) {
    statements.push({
      sql: `COMMENT ON TABLE ${alterPrefix} IS ${spec.comment ? escapeComment(spec.comment) : 'NULL'}`,
    });
  }

  return statements;
}

// ── 库级 DDL（M8-DBDDL / D-19）：PG「库」= schema（D-15）——CREATE / DROP SCHEMA（纯函数）──

export function buildCreateSchemaStatements(spec: DatabaseSpec): DdlStatement[] {
  assertIdentifier('schema 名', spec.name);
  return [{ sql: `CREATE SCHEMA ${quotePgIdentifier(spec.name)}` }];
}

export function buildDropSchemaStatements(db: string): DdlStatement[] {
  assertIdentifier('schema 名', db);
  // CASCADE：schema 内对象连带删除——destructive 红条 + 树删库名称确认承载（D-19）
  return [{ sql: `DROP SCHEMA ${quotePgIdentifier(db)} CASCADE`, destructive: true }];
}
